def eval_rpn(tokens):
    stack = []
    for token in tokens:
        if token in "+-*/":
            b, a = stack.pop(), stack.pop()
            stack.append(int(eval(f"{a}{token}{b}")))
        else:
            stack.append(int(token))
    return stack[0]

